    public static function precioDesde(): string
    {
        $importes = array_map(fn (array $plan) => (int) $plan['mensual'], self::planes());
        $importes = array_filter($importes, fn (int $importe) => $importe > 0);

        if ($importes === []) {
            return '';
        }

        return self::precio(min($importes));
    }

