{"kind":"tool","id":"ZUosCTU2uos","toolName":"write_file","input":{"path":"public/prototipos/pichanguero/b-marcador.css","instructions":"CSS de la propuesta B del prototipo de Pichanguero, aislado del tema real.","content":"@charset "UTF-8";

/*
 * PROTOTIPO — Propuesta B «Marcador» · Pichanguero
 *
 * Hoja aislada del prototipo. Prefijo: .pb-
 * Paleta de la publicidad con otro reparto: claro y de producto.
 */

:root {
    --pb-navy: #101d2d;
    --pb-navy-2: #17293c;
    --pb-lima: #b8f34a;
    --pb-cancha: #1b9447;
    --pb-intenso: #087443;
    --pb-blanco: #ffffff;
    --pb-gris: #f2f5f8;
    --pb-tinta: #0b2239;
    --pb-slate: #5a6b7d;
    --pb-linea: #dce6ee;
    --pb-linea-oscura: #22374b;
    --pb-sombra-suave: 0 18px 40px -30px rgba(11, 34, 57, 0.45);
    --pb-sombra: 0 30px 70px -40px rgba(11, 34, 57, 0.55);
    --pb-radio: 16px;
    --pb-contenedor: 1200px;
    --pb-display: 'Montserrat', 'Inter', system-ui, sans-serif;
    --pb-texto: 'Inter', system-ui, -apple-system, sans-serif;
}

*,
*::before,
*::after {
    box-sizing: border-box;
}

html {
    -webkit-text-size-adjust: 100%;
    scroll-behavior: smooth;
}

body {
    margin: 0;
    background: var(--pb-blanco);
    color: var(--pb-tinta);
    font-family: var(--pb-texto);
    font-size: 16px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

:focus-visible {
