    font-family: var(--pa-texto);
    font-size: 16px;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

a {
    color: inherit;
}

:focus-visible {
    outline: 3px solid var(--pa-limay, #b8f34a);
    outline: 3px solid var(--pa-lima);
    outline-offset: 3px;
    border-radius: 6px;
}

.pa-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
}

.pa-saltar {
    position: absolute;
    left: 1rem;
    top: -4rem;
    z-index: 100;
    padding: 0.75rem 1.25rem;
    background: var(--pa-lima);
    color: var(--pa-navy);
    font-weight: 700;
    text-decoration: none;
    border-radius: 0 0 12px 12px;
    transition: top 0.2s ease;
}

.pa-saltar:focus {
    top: 0;
}

.pa-contenedor {
    width: min(100% - 2.5rem, var(--pa-contenedor));
    margin-inline: auto;
}

/* ============================ CINTA ============================ */

.pa-cinta {
    background: var(--pa-lima);
    color: var(--pa-navy);
    font-size: 0.78rem;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.pa-cinta__interior {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    min-height: 38px;
    padding-block: 0.35rem;
