import puppeteer from 'puppeteer';
import { mkdir } from 'node:fs/promises';

const URL = 'http://127.0.0.1:8000/torneos/demo-landing-pichanguero';
const SALIDA = 'storage/tmp/revision-landing';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

await mkdir(SALIDA, { recursive: true });

const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROME,
    args: ['--no-sandbox', '--hide-scrollbars'],
});

const page = await browser.newPage();
const errores = [];

page.on('console', (msg) => {
    if (msg.type() === 'error') {
        errores.push(`consola: ${msg.text()}`);
    }
});

page.on('requestfailed', (req) => {
    errores.push(`petición fallida: ${req.url()} (${req.failure()?.errorText})`);
});

for (const [ancho, alto] of [[1440, 900], [1024, 768], [390, 844]]) {
    await page.setViewport({ width: ancho, height: alto, deviceScaleFactor: 1 });
    await page.goto(URL, { waitUntil: 'networkidle2', timeout: 60000 });

    // El splash publicitario dura 4,6 s: se espera a que se retire.
    await new Promise((resolve) => setTimeout(resolve, 6500));

    await page.screenshot({ path: `${SALIDA}/hero-${ancho}.png` });
    await page.screenshot({ path: `${SALIDA}/completa-${ancho}.png`, fullPage: true });
}

// Estado del documento: fuentes, ancho, desbordes y colores clave.
await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1 });
await page.goto(URL, { waitUntil: 'networkidle2', timeout: 60000 });
await new Promise((resolve) => setTimeout(resolve, 6500));

const datos = await page.evaluate(() => {
    const raiz = getComputedStyle(document.documentElement);
    const hero = document.querySelector('.se-hero');
    const h1 = document.querySelector('.se-hero__title');

    return {
        fuentes: {
            cuerpo: getComputedStyle(document.body).fontFamily,
            titular: h1 ? getComputedStyle(h1).fontFamily : null,
        },
        colores: {
            fondo: raiz.getPropertyValue('--se-bg').trim(),
            lima: raiz.getPropertyValue('--se-accent').trim(),
            borde: raiz.getPropertyValue('--se-border').trim(),
        },
        desborde: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        altoHeroe: hero ? Math.round(hero.getBoundingClientRect().height) : null,
        textoBoton: (() => {
            const b = document.querySelector('.se-hero__cta .se-btn--primary');

            return b ? `${getComputedStyle(b).textTransform} · ${getComputedStyle(b).fontFamily}` : null;
        })(),
        anclas: [...document.querySelectorAll('.se-nav a')].length,
    };
});

console.log(JSON.stringify({ datos, errores }, null, 2));

await browser.close();
"}}


