 * Comprueba el contenido real de las secciones de la landing con el build
 * de producción: equipos, fixture desplegable, posiciones, premios,
 * galería, app y contacto.
 *
 * Uso: node storage/tmp/comprobar-contenido-landing.mjs
 */

import puppeteer from 'puppeteer';

const URL = 'http://127.0.0.1:8000/torneos/edicion-2026-2026';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';

const browser = await puppeteer.launch({
    headless: 'new',
    executablePath: CHROME,
    args: ['--no-sandbox'],
});

const page = await browser.newPage();
const errores = [];

page.on('console', (msg) => {
    if (msg.type() === 'error') {
        errores.push(msg.text());
    }
});
page.on('response', (res) => {
    if (res.status() >= 400) {
        errores.push(`HTTP ${res.status()}: ${res.url()}`);
    }
});

await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 0.6 });
await page.goto(URL, { waitUntil: 'networkidle2', timeout: 60000 });
await new Promise((resolve) => setTimeout(resolve, 6800));

const antes = await page.evaluate(() => {
    const texto = (sel) => [...document.querySelectorAll(sel)].map((el) => el.textContent.trim());
    const fechas = [...document.querySelectorAll('[data-se-fixture-toggle], .se-fixture__toggle, .se-fixture__head')];

    return {
        equipos: texto('.se-team-card__name').filter(Boolean),
        fechas: fechas.map((el) => el.textContent.trim().replace(/\s+/g, ' ')),
        filasPosiciones: [...document.querySelectorAll('.se-table tbody tr')].map((tr) =>
            tr.textContent.trim().replace(/\s+/g, ' ')
        ),
        premios: texto('.se-prize-card'),
        contacto: texto('#contacto .se-contact-card'),
        galeria: document.querySelectorAll('.se-gallery__item').length,
        seccionApp: !!document.querySelector('#app'),
        enlacesBases: [...document.querySelectorAll('.se-nav a, .se-mobile-nav a')]
            .filter((a) => a.textContent.trim() === 'Bases')
            .map((a) => a.getAttribute('href')),
        partidosVisibles: document.querySelectorAll('.se-fixture__match, .se-fixture__match-row, .se-match-row').length,
    };
});

// Desplegar la primera fecha del fixture
const abierta = await page.evaluate(() => {
    const toggle = document.querySelector('[data-se-fixture-toggle], .se-fixture__toggle');
    if (!toggle) {
        return null;
    }
    toggle.click();
    return true;
});
await new Promise((resolve) => setTimeout(resolve, 700));

const despues = await page.evaluate(() => ({
    partidos: [...document.querySelectorAll('.se-fixture__match, .se-fixture__match-row, .se-match-row')].map((el) =>
        el.textContent.trim().replace(/\s+/g, ' ')
    ),
    abierta: !!document.querySelector('.se-fixture__day.is-open, .se-fixture__group.is-open, [aria-expanded="true"]'),
}));

await page.screenshot({ path: 'storage/tmp/revision-produccion/fixture-abierto.png' });

console.log(JSON.stringify({ antes, toggle: abierta, despues, errores }, null, 2));

await browser.close();
